import React, { useState } from 'react';
import './Login.css'; // tu CSS
import Register from './Register';

const Login = () => {
    const [username, setUsername] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);
        setError('');

        try {
            const response = await fetch('http://localhost:8080/auth/login', {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json'
                },
                body: JSON.stringify({ username, password })
            });

            if (!response.ok) {
                throw new Error('Credenciales incorrectas');
            }

            const data = await response.json();
            console.log('Login OK:', data);

            // Guarda el token
            localStorage.setItem('token', data.token);

            // Podrías redirigir o mostrar mensaje
            alert('Login exitoso!');
        } catch (err) {
            console.error(err);
            setError(err.message);
        } finally {
            setLoading(false);
        }
    };

    return (
    <div className="login-page">
      <h1 className="login-title">CitaSaludEC</h1>
      <div className="login-container">
        <h2>Login</h2>
        <form onSubmit={handleSubmit}>
          <input
            type="text"
            placeholder="Username"
            value={username}
            onChange={(e) => setUsername(e.target.value)}
          />
          <input
            type="password"
            placeholder="Password"
            value={password}
            onChange={(e) => setPassword(e.target.value)}
          />
          <button type="submit">Login</button>
        </form>

        <div style={{ marginTop: '1rem', textAlign: 'center' }}>
          <p style={{ marginBottom: '0.5rem' }}>¿No tienes cuenta?</p>
          <a href="/register" style={{
            display: 'inline-block',
            padding: '0.5rem 1.5rem',
            background: '#00695c',
            color: 'white',
            fontWeight: 'bold',
            textDecoration: 'none',
            borderRadius: '6px',
            transition: 'background 0.3s'
          }}
            onMouseOver={(e) => e.target.style.background = '#004d40'}
            onMouseOut={(e) => e.target.style.background = '#00695c'}
          >
            Registrarse
          </a>
        </div>
      </div>
    </div>
);
}
export default Login;
